import { randomUUID } from "node:crypto";

/**
 * Identifier port.
 *
 * Identity is generated by the application, never by database auto-increment,
 * so that records can be built and related before they are persisted. Tests
 * inject a deterministic generator.
 */
export interface IdGenerator {
  nextId(): string;
}

export const cryptoIdGenerator: IdGenerator = {
  nextId: (): string => randomUUID(),
};
